package com.nkwabyte.cropdiseasedetection.common.data

/**
 * Asante Twi (tw) body text, keyed by [DiseaseInfo.id].
 *
 * See [DiseaseTranslations] for the overlay contract. Ids absent from this map
 * fall back to English, so this file may be filled a few diseases at a time.
 *
 * `localName` is already the Twi vernacular name in the English catalogue —
 * here only its gloss is rendered in Twi.
 *
 * Product names, active ingredients, doses, concentrations and growth stages
 * are kept verbatim, as they appear on the label.
 *
 * Pending native-speaker review.
 */
object TwiDiseaseText {
    val entries: Map<Int, DiseaseTranslation> = mapOf(

        // ── ABURO ─────────────────────────────────────────────────────────────

        0 to DiseaseTranslation(
            localName = "Aburo Nhwiren Tuntum (aburo nhaban nsõ yare)",
            description = "Wɔfrɛ no nso aburo nhaban nsõ yare. Saa mmoawa yare yi yɛ aburo yare a ɛsɛe nneɛma pii wɔ wiase nyinaa. Ɛnyin wɔ ahuhuro ne fɔmm mu, na sɛ ɛba mfe no mfiaseɛ a, ɛbɛtumi asɛe nnɔbaeɛ no kɛseɛ.",
            symptoms = "Nkeka nketewa a ɛte sɛ ahinanan, ɛyɛ birebire kɔsi nsõ, na ɛnenam nhaban no ntini ho. Bere kɔ so a, nkeka no trɛw yɛ ntenten a ɛyɛ nsõ, na ɛka bom sɛe nhaban no fa kɛseɛ. Mfuo a yare no aka no denneennen te sɛ nea ogya ahye no.",
            causes = "Mmoawa a wɔfrɛ no Cercospora zeae-maydis, a ɛtena aburo nwira a aka wɔ asase ani so. Ɛgu ne nsɛso wɔ ahuhuro ne fɔmm mmerɛ mu, na mframa ne osutɔ mpete de kɔ baabiara.",
            effects = "Ɛtew nhaban a ɛyɛ aduane no so, na ɛde nnɔbaeɛ hwere a ɛyɛ ɔha mu 10 kɔsi 50 ba. Yare a ano yɛ den ma dua no ho yɛ mmerɛw, enti ɛhwe ase ansa na wɔatwa. Aburo no su nso tew wɔ mfuo a yare no aka no denneennen mu.",
            prevention = "Fa aba pa a ɛko tia yare no di dwuma. Sesa nnɔbaeɛ — mfa aburo nnua aburo akyi. Fa asase kata nwira a yare aka no so. Ma kwan nna nnua no ntam sɛnea mframa bɛfa mu. Kɔhwɛ afuo no so daa firi mfe no mfimfini.",
            organicMitigation = "• Fa Trichoderma aduro (Trichoderma harzianum) gu asase mu na petepete nso wɔ nhaban so.\n• Petepete neem ngo (Azadirachta indica) nnawɔtwe 3 kɔsi 4 biara.\n• Petepete compost nsuo wɔ nhaban so na ama dua no ahoɔden akɔ soro.\n• Yi nhaban a yare aka no denneennen ne nwira firi hɔ na sɛe wɔn wɔ otwa berɛ akyi.\n• Fa adua ne aburo bom dua na ama yare no kwan atwa mu na asase nso ayɛ pa.",
            chemicalMitigation = "• Azoxystrobin (Quadris): Fa di dwuma firi VT (nhwiren firi) kɔsi R1 (nwi firi) berɛ. San yɛ wɔ nnawɔtwe mmienu akyi sɛ ɛho hia a.\n• Pyraclostrobin + Boscalid (Pristine): Ɛyɛ adwuma yie; fa di dwuma ansa na yare aba.\n• Propiconazole (Tilt): Fa di dwuma sɛ wohu yare no sɛnkyerɛnne a edi kan a; di susudua a ɛwɔ kraataa no so akyi.\n• Trifloxystrobin: Wobetumi de aka propiconazole ho wɔ tank mu na ama ayɛ adwuma kɛse.\n• Sesa aduro ahorow no daa na yare no antumi angyina ano."
        ),

        1 to DiseaseTranslation(
            localName = "Aburo Nhwiren Atoro (aburo nhaban kɔkɔɔ yare)",
            description = "Mmoawa yare a ɛtrɛw ntɛm wɔ awɔw ne fɔmm mu. Nkurukuruwa kɔkɔɔ a ɛte sɛ ntayaa pupu wɔ nhaban no afanu nyinaa so. Ɛtrɛw wɔ Afrika Atɔeɛ Fam, Ghana ka ho, titiriw wɔ anɔpa a awɔw ne bosuo wɔ hɔ.",
            symptoms = "Nkurukuruwa a ɛyɛ mfuturu, ɛyɛ birebire kɔsi kɔkɔɔ te sɛ ntayaa, ɛwɔ nhaban no soro ne aseɛ nyinaa. Akyire yi wɔ mfe no mu no, nkurukuruwa no dan tuntum. Nhaban a yare no aka no denneennen dan sɛ akokɔsradeɛ na ewu ansa na ne berɛ aso.",
            causes = "Mmoawa a wɔfrɛ no Puccinia sorghi. Mframa de ne nsɛso firi anafoɔ fam mmeaeɛ ba. Awɔw (16 kɔsi 23 °C) ne bosuo a ɛtena nhaban so kyɛ (dɔnhwerew 6 ne nea ɛboro so) boa yare no.",
            effects = "Ɛtew aduane a dua no yɛ no so, na ɛde ɔha mu 5 kɔsi 40 hwere ba, sɛnea berɛ a yare no bae te. Yare a ɛba ntɛm ansa na nhwiren afiri no na ɛsɛe adeɛ paa. Nnua a yare aka no denneennen so aba yɛ hare na ɛnyɛ ma yie.",
            prevention = "Dua aba ahorow a ɛko tia yare no — eyi ne ɔkwan pa a ɛkyɛ. Adua a wɔdua no ntɛm tew berɛ a nsɛso no dɔɔso no so. Sɛe aburo a efifi n'ankasa ne nnua foforɔ a yare no tena wɔn so. Hwɛ afuo no so nnawɔtwe biara firi V8 berɛ.",
            organicMitigation = "• Dua aburo ahorow a ɛko tia yare no wɔ abɔdeɛ mu (bisa aba tɔnfoɔ a wɔwɔ wo mpɔtam).\n• Sɛe nwira a yare aka no ne aburo a efifi n'ankasa wɔ otwa akyi.\n• Petepete neem ngo (ɔha mu 2 kɔsi 3) sɛ wohu yare no sɛnkyerɛnne a edi kan a.\n• Sulfur mfuturu anaa sulfur a ɛnane wɔ nsuo mu betumi asi yare a ɛba ntɛm ano.\n• Hwɛ hu sɛ potassium bebree wɔ asase no mu — nnua a enni bi no nya yare ntɛm.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Aduro a ɛbɔ ho ban; fa di dwuma sɛ nkurukuruwa a edi kan fiti a.\n• Propiconazole (Tilt 250 EC): Ɛkɔ dua no mu; fa di dwuma ansa na VT aba na ama ayɛ adwuma yie.\n• Tebuconazole (Folicur): Ɛyɛ adwuma yie; fa di dwuma sɛ yare no du afuo no ɔha mu 5 a.\n• Azoxystrobin: Ɛbɔ ho ban na esa yare nso.\n• Fa aduro no di dwuma ansa na nwi afiri sɛ nhaban kɔkɔɔ wɔ hɔ a — sɛ wode di dwuma akyire a, mfaso nni so kɛse."
        ),

        2 to DiseaseTranslation(
            localName = "Aburo Pa (aburo a ɛwɔ ahoɔden)",
            description = "Aburo dua yi nkyerɛ yare, mmoawa ɔsɛeɛ, anaa aduane hia biara sɛnkyerɛnne. Aburo a ɛwɔ ahoɔden no nhaban yɛ ahabammono a ɛhyerɛn na ɛyɛ den, na ɛrekɔ so aso nnɔbaeɛ pa.",
            symptoms = "Nhaban ahabammono a ɛyɛ pɛ na ɛhyerɛn, nkeka birebire, ntenten, akokɔsradeɛ anaa nwuo nni ho. Nnua a ɛyɛ den na egyina, nhwiren a afiri yie, ne aburo a ɛso pɛ a nwi kata so yie.",
            causes = "Asase a ɛwɔ aduane pa, osutɔ anaa nsuo a wɔgugu so daa, aba pa a wɔasɔ ahwɛ, nnua dodow a ɛfata, ne afuo mu nneyɛeɛ pa nyinaa.",
            effects = "Nnɔbaeɛ pii, aburo a mu yɛ duru, nnua a ɛyɛ den na ɛnhwe ase. Dua no betumi aso ne nnɔbaeɛ nyinaa na nea ɛbɛsɛe wɔ otwa akyi nso yɛ kakraa bi.",
            prevention = "Kɔ so yɛ deɛ woreyɛ no. Nantew afuo no mu daa (nnawɔtwe biara pɛ) na woahu yare anaa mmoawa sɛnkyerɛnne a edi kan ansa na ayɛ kɛse. Twerɛ nneɛma a wode di dwuma nyinaa gu hɔ na aboa wo daakye.",
            organicMitigation = "• Kɔ so fa compost anaa abɔdeɛ nneɛma gu asase mu na asase no nkwa ntena hɔ.\n• Sesa nnɔbaeɛ na fa adua (adua, soya) di akyi na nitrogen nkɔ soro wɔ abɔdeɛ kwan so.\n• Fa nnɔbaeɛ ahorow bom dua na woanya afuo no ho mfaso na nwura anfifi.\n• Kɔ so petepete aduane nketewa wɔ nhaban so sɛ woreyɛ a.\n• Si nsuo akorabea (nkoroo, nwura a wode kata asase so) na nsuo ntena asase mu.",
            chemicalMitigation = "• Fa NPK sumina a ɛfata (te sɛ 15-15-15 anaa 23-10-5) di dwuma wɔ susudua a wɔaka no so.\n• Fa urea (46-0-0) gu dua no nkyɛn wɔ kotodwe berɛ (V6) na nitrogen nkɔ soro.\n• Fi aduro a ɛbɔ ho ban ase wɔ nhwiren berɛ mu sɛ mfe a atwam no yare wɔ hɔ a.\n• Mfa mmoawa aduro nni dwuma mma dua mu ntɔfe gye sɛ ɔsɛeɛ no du ɔha mu 10.\n• Di CABI anaa MoFA (Ghana Aduane ne Kuadwuma Amanyɔfo) petepete nhyehyɛeɛ akyi."
        ),

        3 to DiseaseTranslation(
            localName = "Aburo Nhwiren Ohow (aburo nhaban hyew yare)",
            description = "Mmoawa yare a ɛsɛe adeɛ. Ɛtew nhaban so ntɛm na ɛtew aduane a dua no yɛ so kɛse. Nkeka akɛseɛ a ɛte sɛ sigaret, ɛyɛ birebire, ne ne sɛnkyerɛnne titiriw. Ano yɛ den paa wɔ mmeaeɛ a ahuhuro nnɔɔso na bosuo tena hɔ kyɛ, te sɛ Ghana kwaeɛ mmeaeɛ.",
            symptoms = "Nkeka akɛseɛ atenten a ɛte sɛ sigaret (sentimita 3 kɔsi 15), ɛyɛ nsõ-ahabammono kɔsi birebire, na ɛnenam nhaban no ntini ho. Ɛfiri nhaban a ɛwɔ ase no so na ɛforo kɔ soro. Nhaban fa a yare aka no dan birebire anaa nsõ, na ebetumi ayɛ tuntum bere a mmoawa no regu ne nsɛso.",
            causes = "Mmoawa Exserohilum turcicum (kane no na wɔfrɛ no Helminthosporium turcicum). Ɛtena aburo nwira mu. Ahuhuro a ɛnnɔɔso (18 kɔsi 27 °C) ne bosuo a ɛtena nhaban so kyɛ (dɔnhwerew 6 ne nea ɛboro so) boa no. Mframa ne osutɔ mpete de ne nsɛso kɔ.",
            effects = "Ebetumi de ɔha mu 30 kɔsi 50 hwere ba sɛ ɛba ansa na nhwiren afiri anaa ne berɛ mu a. Nhaban a ɛtew kɛse no tew aburo no mma ne ne duru so. Yare a ano yɛ den na ɛba ntɛm betumi ama nnɔbaeɛ no asɛe koraa wɔ aba a ɛnko ntia so.",
            prevention = "Dua aba a ɛko tia yare no — eyi ne adeɛ a ɛho hia sen biara. Sesa nnɔbaeɛ na fa nnua a ɛnyɛ nwura ahorow (adua, atosodeɛ) di akyi. Fa asase kata nwira a yare aka no so wɔ otwa akyi na ama yare nsɛso no so atew. Mfa nitrogen pii nni dwuma, ɛfiri sɛ ɛma dua no yɛ mmerɛw na ɛnya yare ntɛm.",
            organicMitigation = "• Fa aburo ahorow a ɛko tia yare no di dwuma (hwehwɛ ahorow a CSIR-SARI anaa IITA akamfo wɔ Ghana).\n• Fa Trichoderma harzianum gu asase mu na petepete nso wɔ nhaban so.\n• Neem aba a woayam gu asase mu tew yare nsɛso a ɛwɔ asase mu no so.\n• Yi nnua fa a yare aka no firi hɔ na sɛe wɔ otwa akyi — nnyaa nwira wɔ afuo no mu.\n• Fa adua ne aburo bom dua na ama yare no kwan atwa mu.",
            chemicalMitigation = "• Propiconazole (Tilt 250 EC): Fa di dwuma wɔ V8–V10 berɛ ansa na nhwiren afiri; san yɛ nnansa 14 biara.\n• Azoxystrobin: Ɛyɛ adwuma yie sɛ ɔbanbɔ; fa di dwuma sɛ wohu yare sɛnkyerɛnne a edi kan a.\n• Pyraclostrobin + Metconazole (Headline AMP): Ɛsa yare ahorow pii; ɛyɛ papa ma saa yare yi.\n• Mancozeb: Aduro a ɛbɔ ho ban; fa di dwuma ansa na yare aba bere a wim tebea fata no.\n• Aduro a wɔde di dwuma ansa na nwi afiri no na mfaso wɔ so sen biara."
        ),

        4 to DiseaseTranslation(
            localName = "Aburo Nhwiren Mfirimiri (aburo nhaban ntenten yare)",
            description = "Aburo nhaban ntenten yare ne aburo mmoawa nketewa yare a ɛsɛe adeɛ sen biara wɔ Afrika. Maize Streak Virus (MSV) na ɛde ba, na mmoawa a wɔfrɛ no leafhopper na ɛsoa. Ɛwɔ Afrika a ɛwɔ Sahara anafoɔ fam nyinaa, Ghana ka ho. Aba a ɛnko ntia no betumi ahwere nnɔbaeɛ no nyinaa.",
            symptoms = "Ntenten nketewa a ɛtwa mu mu, ɛyɛ fitaa-akokɔsradeɛ, pue wɔ nhaban ntini ho, na ɛyɛ nhwɛso a ɛyɛ ahabammono fitaa kɔsi akokɔsradeɛ. Nnua a yare no aka wɔn denneennen no nnyin na wɔn aburo yɛ nketewa anaa ɛnyɛ pa. Wɔ awieeɛ no, nhaban betumi ayɛ fitaa na adan akokɔsradeɛ koraa.",
            causes = "Maize Streak Virus (MSV), Geminivirus a mmoawa leafhopper (Cicadulina spp.) soa. Mmoawa nketewa no ntumi mfa asase anaa nsɔmu nkɔ — ɛhia mmoawa no. Leafhopper dɔɔso wɔ ahuhuro ne ɔpɛ berɛ mu.",
            effects = "Nnɔbaeɛ hwere a ɛyɛ ɔha mu 30 kɔsi 100, sɛnea aba no ne dua no mfe te bere a yare no bae. Yare a ɛba ntɛm (nnawɔtwe mmienu akyi a efifi) ma nnɔbaeɛ no sɛe koraa. Nnua a wɔnnyinii no nso aburo a mfaso wɔ so biara. Eyi yɛ ɔhaw kɛse ma akuafoɔ nketewa wɔ Ghana.",
            prevention = "Ɔkwan pa sen biara ne sɛ wobɛdua aba a ɛko tia MSV — nea ɛwɔ ɔko no mu ahoɔden (te sɛ STRIGA 6, STRIGA 4, anaa aba a IITA ayi adi). Adua a wɔdua no ntɛm tew berɛ a leafhopper dɔɔso no so. Yi nwura firi afuo no nkyɛn, ɛfiri sɛ ɛhɔ na leafhopper tena.",
            organicMitigation = "• Dua aba a wɔasɔ ahwɛ sɛ ɛko tia MSV (wɔkamfo eyi paa).\n• Dua ntɛm (osutɔ mfiaseɛ): nnua no bɛnyin ansa na leafhopper adɔɔso.\n• Fa aburo ne adua anaa bankye bom dua na leafhopper nantew ho asi.\n• Tu nnua a yare aka wɔn denneennen no ntɛm na mmoawa nketewa no tenabea so ntew.\n• Ma afuo no nkyɛn nyɛ hɔ a nwura nni, ɛfiri sɛ ɛhɔ na leafhopper hyɛ.\n• Firi akokɔsradeɛ a ɛkyere nneɛma boa ma wohu leafhopper dodow.",
            chemicalMitigation = "• Imidacloprid aba aduro (Gaucho 600 FS): Ɛyɛ adwuma yie na ɛbɔ nnua nketewa ho ban firi leafhopper ka mu wɔ nnawɔtwe 3 a edi kan a ɛho hia no mu.\n• Thiamethoxam aba aduro (Cruiser): Imidacloprid ananmusi ma ɔbanbɔ a ɛba ntɛm.\n• Mmoawa aduro a wɔpetepete (Dimethoate, Chlorpyrifos): Fa di dwuma tia leafhopper sɛ woamfa aduro anka aba no ho a; fa di dwuma sɛ wohu leafhopper a edi kan a.\n• Hyɛ no nsow: Mmoawa aduro kum mmoawa no nanso ɛnsa dua a yare aka no yare. Fa w'adwene si ɔbanbɔ so."
        ),

        // ── MAKO ──────────────────────────────────────────────────────────────

        5 to DiseaseTranslation(
            localName = "Mako Nhwiren Ponko (mako nhaban nkeka yare)",
            description = "Mmoawa nketewa yare a ɛsɛe adeɛ. Ɛka mako nhaban, dua ne n'aba wɔ ahuhuro ne fɔmm mu. Ɛtrɛw wɔ Ghana mmeaeɛ a fɔmm wɔ hɔ. Nhaban a ɛtew ntɛm ne nkeka a ɛba aba so de ɔsɛeɛ kɛse ba, titiriw ma mako a wɔde kɔ amanɔne.",
            symptoms = "Nkeka nketewa a ɛyɛ kurukuruwa, ɛyɛ tuntum na ɛte sɛ nsuo aka mu, wɔ nhaban so (milimita 2 kɔsi 10), na ɛdan birebire a akokɔsradeɛ atwa ho ahyia. Nkeka no betumi aka abom ayɛ mmeaeɛ akɛse a awu. Nhaban a ɛdan akokɔsradeɛ na ɛtew no ma awia ka aba no. Aba no nya nkeka tuntum a ɛpagya te sɛ ɔhonam ani kurow, na ɛtew ne boɔ so wɔ gua so.",
            causes = "Mmoawa nketewa Xanthomonas campestris pv. vesicatoria (ne X. perforans ne X. euvesicatoria nso). Ɛfa osutɔ mpete, nsuo a wɔgu firi soro, nnwinnadeɛ a yare aka, aba a yare aka, ne nnua a wɔdua so trɛw. Ahuhuro (25 kɔsi 30 °C) ne bosuo a ɛwɔ nhaban so boa no.",
            effects = "Nhaban a ɛtew kɛse ma dua no yɛ mmerɛw na ɛma awia ne yare foforɔ ka aba a ɛrenyin no. Nkeka a ɛba aba so tew ne boɔ so ɔha mu 40 kɔsi 60. Nnɔbaeɛ hwere betumi adu ɔha mu 50 wɔ osutɔ berɛ mu. Wɔpo mako a wɔde kɔ amanɔne esiane nkeka no nti.",
            prevention = "Fa aba ne nnua a wɔasɔ ahwɛ sɛ yare nni wɔn ho nkutoo di dwuma, firi adetɔnfoɔ a wɔdi nokware hɔ. Ngu nsuo mfiri soro — fa nsuo a ɛsensen anaa nsuo a ɛnenam nkoroo mu di dwuma. Tew nantew a wonantew wɔ afuo a fɔmm wɔ mu so. Hohoro nnwinnadeɛ ho wɔ dua biara akyi. Sesa nnɔbaeɛ mfe 2 kɔsi 3 na fa nnɔbaeɛ a ɛnyɛ mako abusua di akyi.",
            organicMitigation = "• Fa kɔbere aduro a wɔapene so ma abɔdeɛ kuadwuma di dwuma (Bordeaux mixture: kɔbere sulfate ɔha mu 1 + aboɔ nkyene) sɛ ɔbanbɔ nnansa 7 kɔsi 10 biara.\n• Fa neem ngo (ɔha mu 2) ne castile samina (ɔha mu 0.5) petepete na ama mmoawa nketewa no so atew na dua no ahoɔden akɔ soro.\n• Yi nhaban a yare aka ne nwira firi hɔ na sɛe wɔn.\n• Fa nneɛma kata dua no ase na asase mpete nkɔ nhaban a ɛwɔ ase no so.\n• Compost a wɔde gu asase mu ma asase no nkwa yɛ pa na dua no nya ahoɔden.",
            chemicalMitigation = "• Copper hydroxide (Kocide 3000): Eyi na wɔde di dwuma kɛse; fa di dwuma nnansa 7 biara wɔ fɔmm berɛ mu.\n• Copper oxychloride + Mancozeb (Cuprosan): Nkabom a ɛyɛ adwuma ma mmoawa nketewa ne mmoawa yare.\n• Streptomycin sulfate (baabi a mmara ma kwan): Fa di dwuma wɔ yare no mfiaseɛ, na sesa no ne kɔbere ntam.\n• Acibenzolar-S-methyl (Actigard): Ɛma dua no ankasa ahoɔden sɔre — fa ka kɔbere ho.\n• Mfa kɔbere nni dwuma wɔ ahuhuro ne awia denden mu na ansɛe dua no."
        ),

        6 to DiseaseTranslation(
            localName = "Mako Nhwiren Akyekyere (mako nhaban aponkyerene ani yare)",
            description = "Wɔfrɛ no nso aponkyerene ani nkeka yare. Saa mmoawa yare yi de nkeka kurukuruwa a emu yɛ fitaa na ne nkyɛn yɛ tuntum ba, te sɛ aponkyerene ani. Ɛbu so wɔ Ghana wɔ fɔmm ne osutɔ berɛ mu. Yare a ɛba mpɛn pii wɔ mfe no mu ma nhaban tew nkakrankakra.",
            symptoms = "Nkeka kurukuruwa (milimita 5 kɔsi 15) a emu yɛ birebire kɔsi nsõ na ne nkyɛn yɛ birebire tuntum kɔsi beredum. Emu no betumi atew ama tokuro aka hɔ. Nhaban dan akokɔsradeɛ twa nkeka no ho hyia na awieeɛ no ɛtew. Yare a ano yɛ den ma nhaban nyinaa tew.",
            causes = "Mmoawa Cercospora capsici. Ɛtena nnua nwira a yare aka mu. Wɔgu ne nsɛso na ɛtrɛw wɔ ahuhuro (25 kɔsi 30 °C), fɔmm ne osutɔ mu. Wɔfa aba a yare aka so nso de trɛw.",
            effects = "Nhaban a ɛtew nkakrankakra tew aduane a dua no yɛ so na ɛma awia ka aba no. Nnɔbaeɛ hwere a ɛyɛ ɔha mu 20 kɔsi 40 bu so wɔ mfuo a wɔnhwɛ so mu. Nhaban a ɛtew mpɛn pii ma dua no yɛ mmerɛw na ɛnya yare foforɔ ntɛm.",
            prevention = "Dua firi aba a wɔasɔ ahwɛ sɛ ɛho tew mu. Ma kwan nna (sentimita 60 wɔ nnua ntam) na mframa afa mu. Yi nnua fa a yare aka firi hɔ ntɛm. Sesa nnɔbaeɛ mfe 2 pɛ na fa nnɔbaeɛ a ɛnyɛ mako abusua di akyi.",
            organicMitigation = "• Petepete kɔbere sulfate (Bordeaux mixture) sɛ ɔbanbɔ nnansa 10 kɔsi 14 biara.\n• Petepete neem ngo ne bicarbonate nkabom (baking soda atere ketewa 1 + neem ngo atere kɛse 1 wɔ lita biara mu).\n• Yi nhaban ne nwira a yare aka nyinaa firi hɔ na sɛe wɔn.\n• Fa Trichoderma harzianum gu asase mu sɛ nsuo na ama yare nsɛso a ɛwɔ asase mu no so atew.\n• Kwan pa ne dua a wotwitwa ma mframa fa mu na fɔmm a ɛwɔ dua no ho so tew.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Ɛbɔ ho ban; fa di dwuma nnansa 7 kɔsi 10 biara wɔ fɔmm berɛ mu.\n• Chlorothalonil (Bravo 500): Ɛbɔ ho ban yie; fa di dwuma nnansa 7 kɔsi 14 biara.\n• Azoxystrobin (Amistar): Ɛkɔ dua no mu; fa di dwuma sɛ wohu yare sɛnkyerɛnne a edi kan a.\n• Difenoconazole (Score 250 EC): Ɛkɔ dua no mu; fa di dwuma nnansa 14 biara na ɛsa yare no.\n• Sesa aduro abusua ahorow no wɔ nsa 2 kɔsi 3 biara akyi na yare no antumi angyina ano."
        ),

        7 to DiseaseTranslation(
            localName = "Mako Nhwiren Ohow (mako nhaban hyew yare)",
            description = "Mmoawa yare a ɛka nhaban dedaw a ɛwɔ ase no kane, na ɛyɛ nkeka a nkyerɛnkyerɛmu atwa ho ahyia te sɛ nea wɔtow tuo gu so. Ɛbu so wɔ Ghana mako mmeaeɛ nyinaa, titiriw wɔ osutɔ berɛ mu bere a ahuhuro ne fɔmm tena hɔ.",
            symptoms = "Nkeka birebire kɔsi tuntum (milimita 10 kɔsi 15) a nkyerɛnkyerɛmu atwa ho ahyia ma ɛte sɛ nea wɔtow tuo gu so, kane wɔ nhaban dedaw a ɛwɔ ase so. Akokɔsradeɛ betumi atwa nkeka no ho ahyia. Nkeka no ma nhaban dan akokɔsradeɛ na ɛtew. Sɛ ano yɛ den a, nhaban tew kɔ soro ntɛm.",
            causes = "Mmoawa Alternaria capsici anaa A. alternata. Wɔwɔ asase mu ne aba mu nyinaa. Wɔtena nwira a yare aka mu. Ahuhuro (24 kɔsi 29 °C), fɔmm kɛse, ne nsuo ne ɔpɛ a ɛsesa boa wɔn.",
            effects = "Nhaban a ɛtew firi dua no ase kɔ soro, na ɛtew aduane a dua no yɛ so kɛse. Aba a ɛda hɔ no hyew wɔ awia mu na ɛporɔw. Sɛ wɔanhwɛ so a, nnɔbaeɛ hwere betumi adu ɔha mu 30 kɔsi 50 wɔ mfuo a yare aka no denneennen mu.",
            prevention = "Gu nsuo dua no ase nkutoo — mma nsuo nnka nhaban. Sesa nnɔbaeɛ mfe 2 pɛ na fa nnua a ɛnyɛ mako abusua di akyi. Fa dua si nnua no ho na nhaban anka asase. Yi nhaban a ɛwɔ ase a ɛka asase no firi hɔ. Mfa nitrogen pii nni dwuma, ɛfiri sɛ ɛma dua no yɛ mmerɛw na ɛnya yare.",
            organicMitigation = "• Fa compost kata dua no ase (mu tenten sentimita 5) na asase mpete nkɔ nhaban so.\n• Petepete kɔbere sulfate (Bordeaux mixture) sɛ ɔbanbɔ.\n• Petepete neem ngo (ɔha mu 2 kɔsi 3) na ama mmoawa yare no nnyin.\n• Bicarbonate ne neem ngo a wɔpetepete wɔ nhaban so sesa nhaban ani tebea na esi mmoawa yare kwan.\n• Yi nhaban a ɛwɔ ase a yare aka no firi hɔ ntɛm sɛ wohu a.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500): Fa di dwuma nnansa 7 kɔsi 10 biara sɛ ɔbanbɔ wɔ fɔmm berɛ mu.\n• Iprodione (Rovral): Aduro a ɛsa Alternaria; fa di dwuma wɔ yare no mfiaseɛ.\n• Azoxystrobin (Amistar): Ɛkɔ dua no mu; fa di dwuma sɛ ɔbanbɔ wɔ adua berɛ mu na nnansa 14 biara.\n• Boscalid + Pyraclostrobin (Bellis): Nkabom pa a ɛyɛ adwuma tia Alternaria.\n• Copper oxychloride: Fa di dwuma sɛ ɔbanbɔ nnansa 10 biara wɔ osutɔ berɛ mu."
        ),

        8 to DiseaseTranslation(
            localName = "Mako Kobuo (mako nwuo yare)",
            description = "Mmoawa yare a ɛwɔ asase mu na ɛsɛe adeɛ paa. Ɛkɔ mako dua no nsuo akwan mu, na ɛma dua no wu nkakrankakra kɔsi sɛ ebewu. Sɛ ɛba afuo bi mu a, ɛtena asase no mu mfe pii. Ɛbu so wɔ Ghana mako a wɔgu nsuo so mu.",
            symptoms = "Nhaban a ɛwɔ ase dan akokɔsradeɛ na ɛforo kɔ soro. Dua no mman wu wɔ awia ahuhuro mu, na sɛ wogu nsuo so mpo a ɛnnyɛ yie. Nnua no hwe ase wu awieeɛ no. Dua no mu sesa n'ahosuo — sɛ wotwa dua no wɔ ase a wuhu ntenten birebire kɔsi kɔkɔɔ.",
            causes = "Mmoawa Fusarium oxysporum f.sp. capsici a ɛwɔ asase mu. Ɛfa nhini akuru anaa abɔdeɛ akwan so kɔ mu. Ɛtena asase mu mfe 20 ne nea ɛboro so sɛ chlamydospores. Asase a ahuhuro wɔ mu (25 kɔsi 30 °C), nsuo pii wɔ ɔpɛ akyi, ne asase a nsuonwono wɔ mu boa no.",
            effects = "Dua no wu wɔ nna anaa nnawɔtwe kakraa bi akyi. Nnɔbaeɛ no nyinaa betumi asɛe sɛ afuo no nyinaa nya yare no a. Asase no kɔ so kura yare no mfe pii — mako a wobedua wɔ hɔ daakye behu amane. Ayaresa biara nni hɔ sɛ dua no nya yare no a.",
            prevention = "Nnua mako bio wɔ afuo a saa yare yi baa mu pɛn mu kosi mfe 5. Ma asase no pH nkɔ 6.5 soro denam aboɔ nkyene a wode gu mu so. Ma nsuo mfiri asase no mu yie — mma nsuo nnyina hɔ. Hohoro nnua a wode dua no ho. Fa nnua nketewa firi ɔdua a wɔasɔ ahwɛ nkutoo hɔ.",
            organicMitigation = "• Asase hyew wɔ awia mu: Fa plastik a ani da hɔ kata asase a fɔmm wɔ mu so nnawɔtwe 4 kɔsi 6 wɔ ahuhuro berɛ mu na yare nsɛso a ɛwɔ asase mu so bɛtew kɛse.\n• Fa Trichoderma harzianum gu asase mu (sɛ nsuo anaa fa ka dua tokuro ho): ɛtena nhini ho na esi Fusarium kwan.\n• Fa mmoawa pa (Glomus spp.) gu nhini ho wɔ adua berɛ mu na nhini no ahoɔden nkɔ soro.\n• Fa neem aba a woayam gu asase mu — ɛkum Fusarium.\n• Fa aba a ɛko tia yare no di dwuma baabi a ɛwɔ.",
            chemicalMitigation = "• Metalaxyl (Ridomil): Gu asase mu wɔ adua berɛ mu sɛ ɔbanbɔ; ɛnsa dua a yare aka no yare.\n• Carbendazim (Bavistin): Gu asase mu anaa fa yɛ aba aduro; fa di dwuma sɛ ɔbanbɔ nkutoo.\n• Thiram aba aduro: Ɛbɔ nnua nketewa nhini ho ban wɔ nyin berɛ mu.\n• Fludioxonil: Aba aduro a ɛyɛ adwuma tia Fusarium ase porɔw.\n• Ɛho hia: Aduro biara nsa yare no sɛ ɛda mu dedaw a — ɔbanbɔ ne adeɛ titiriw."
        ),

        9 to DiseaseTranslation(
            localName = "Mako Pa (mako a ɛwɔ ahoɔden)",
            description = "Mako dua yi wɔ ahoɔden pa: nhaban ahabammono a ɛyɛ tuntum, nnua a ɛyɛ den, ne aba a ɛrenyin yie. Mako a ɛwɔ ahoɔden kyerɛ sɛ wɔredi kuadwuma akwan pa akyi na nnɔbaeɛ no bɛyɛ pa.",
            symptoms = "Nhaban ahabammono tuntum a ɛhyerɛn, ne nkyɛn yɛ tromtrom, nkeka anaa akokɔsradeɛ nni ho. Nnua a ɛyɛ den na egyina. Nhwiren bebree, fitaa anaa beredum. Mako a ɛyɛ den na ɛhyerɛn, ɛso fata na ɛho nni dɛm biara.",
            causes = "Asase pa (pH 6.0 kɔsi 6.8), nsuo a wɔhwɛ so daa, kwan a ɛda nnua ntam, aduane a ɛkari pɛ (NPK ne aduane nketewa), ne mmoawa ne nwura a wɔhwɛ so yie.",
            effects = "Aba pii a ɛfata gua so. Nnua a ɛyɛ den gyina ɔpɛ ne yare ano. Nnɔbaeɛ a ɛba daa boa okuafoɔ sika ne fie mu aduane.",
            prevention = "Ma asase no nsuo ntena hɔ daa denam nsuo a ɛsensen anaa nsuo a wogu so daa so. Fa nneɛma kata asase so na nsuo ntena mu na nwura anfifi. Hwɛ so daa na woahu mmoawa ne nyarewa sɛnkyerɛnne a edi kan. Twerɛ afuo no ho nsɛm gu hɔ na woatumi adi nea wode di dwuma ne nea wonya akyi.",
            organicMitigation = "• Fa compost a aporɔw yie (kilo 2 kɔsi 3 ma dua biara) gu mu wɔ adua berɛ mu ne akyire yi.\n• Fa nwura anaa sare a awo (sentimita 8 kɔsi 10) kata asase so na nsuo ntena mu na nwura anfifi.\n• Dua basil anaa marigold gu mako no ho na ɛbɛpam mmoawa ne ntutummɛ fitaa wɔ abɔdeɛ kwan so.\n• Petepete neem ngo sɛ ɔbanbɔ nnawɔtwe 2 kɔsi 3 biara na ɛbɛpam mmoawa na mmoawa yare nketewa nso so atew.\n• Petepete nsuomnam nsuo anaa nnua nsuo a akaw wɔ nhaban so na dua no ahoɔden nkɔ soro.",
            chemicalMitigation = "• Fa NPK sumina a ɛkari pɛ di dwuma (te sɛ 12-12-17 wɔ aba berɛ mu).\n• Fa calcium nitrate ka ho na aba no ase amporɔw.\n• Fa magnesium sulfate (Epsom salt a wɔpetepete wɔ nhaban so) sɛ wuhu akokɔsradeɛ wɔ ntini ntam a.\n• Petepete kɔbere sɛ ɔbanbɔ wɔ osutɔ berɛ mfiaseɛ.\n• Fa mmoawa aduro ka aba ho wɔ ɔdua berɛ mu na ɛbɔ nnua nketewa ho ban."
        ),

        10 to DiseaseTranslation(
            localName = "Mako Nhwiren Kwanee (mako nhaban wuo yare)",
            description = "Yare a ɛsɛe adeɛ paa a Phytophthora infestans de ba (yare koro no ara na ɛde Ireland ɔkɔm kɛse no bae). Ebetumi asɛe mako mfuo nyinaa wɔ nna kakraa bi mu wɔ awɔw ne fɔmm mu. Ɛtrɛw ntɛm paa enti ɛyɛ nyarewa a wosuro no wɔ wiase nyinaa mu baako.",
            symptoms = "Nkeka tuntum a ɛte sɛ wɔasra ngo na ɛte sɛ nsuo aka mu, wɔ nhaban ne nnua so, na ɛtrɛw ntɛm. Mmoawa fitaa a ɛte sɛ asaawa wɔ nhaban ase wɔ fɔmm mu. Nnua nya nkeka birebire tuntum na ebetumi ahwe ase. Aba nya nkeka birebire tuntum a ɛyɛ den.",
            causes = "Phytophthora infestans (ɛnyɛ mmoawa yare ankasa). Ɛfa mframa so trɛw wɔ awɔw (15 kɔsi 20 °C) ne fɔmm mu. Ebetumi atu kwan kilomita pii wɔ mframa mu. Ɛnyin wɔ anadwo awɔw ne anɔpa bosuo mu.",
            effects = "Afuo no nyinaa betumi asɛe wɔ nnansa 3 kɔsi 7 mu sɛ wim tebea fata a. Sɛ yare no ka aba no a, wontumi ntɔn. Sika hwere kɛse, titiriw wɔ mfe no awieeɛ osutɔ berɛ mu wɔ Ghana.",
            prevention = "Nnua nnua no mmɛn wɔn ho — ma mframa mfa wɔn ntam. Ngu nsuo mfiri soro. Di wim nsɛm akyi wɔ awɔw ne osutɔ berɛ mu na fa aduro di dwuma ansa na yare aba. Yi dua biara a yare aka firi hɔ na hyew no ntɛm ara. Nnyaa nwira a yare aka wɔ afuo no mu.",
            organicMitigation = "• Bordeaux mixture (kɔbere sulfate ɔha mu 1 + aboɔ nkyene): Fa di dwuma nnansa 5 kɔsi 7 biara wɔ awɔw ne fɔmm mu sɛ ɔbanbɔ denden.\n• Yi nnua ne nhaban a yare aka nyinaa firi hɔ ntɛm ara — fa hyɛ kotoku mu na hyew; mfa nyɛ compost.\n• Ma nsuo mfiri afuo no mu yie na nsuo nnyina hɔ.\n• Nnua wɔ mmeaeɛ a ɛba fam a mframa awɔw boa ano.\n• Fa kɔbere samina (copper octanoate) di dwuma sɛ nea wɔapene so ma abɔdeɛ kuadwuma.",
            chemicalMitigation = "• Metalaxyl + Mancozeb (Ridomil Gold MZ): Ɛyɛ adwuma sen biara; fa di dwuma sɛ ɔbanbɔ nnansa 7 kɔsi 10 biara wɔ awɔw ne fɔmm mu.\n• Cymoxanil + Mancozeb (Curzate M): Ɛbɔ ho ban na ɛsa yare nso; fa di dwuma nnansa 5 kɔsi 7 biara.\n• Dimethomorph (Forum): Ɛkɔ dua no mu; ɛyɛ adwuma tia Phytophthora; sesa no ne Ridomil ntam.\n• Fosetyl-aluminum (Aliette): Ɛkɔ dua no mu denam nhini ne nhaban so; fa di dwuma sɛ ɔbanbɔ.\n• Sesa aduro ahorow no wɔ nsa 2 kɔsi 3 biara akyi na yare no antumi angyina ano."
        ),

        11 to DiseaseTranslation(
            localName = "Mako Nhwiren Opapaee (mako nhaban porɔw yare)",
            description = "Din a ɛkyerɛ nhaban wuo ntɛm a mmoawa yare anaa mmoawa nketewa de ba wɔ mako so. Nkeka akɛseɛ tuntum a wɔn su nni hɔ na ɛtrɛw ntɛm na ɛyɛ ne sɛnkyerɛnne, na ɛma nhaban wu na dua no yɛ mmerɛw.",
            symptoms = "Mmeaeɛ akɛseɛ birebire tuntum anaa nea ɛte sɛ nsuo aka mu, a wɔn su nni hɔ, ɛfiri nhaban nkyɛn anaa ne ti so. Nhaban fa no wu ntɛm na ɛdan birebire te sɛ kraataa. Yare a ano yɛ den ma nhaban nyinaa wu na ɛtew, na dua no ka hɔ kwaterekwa.",
            causes = "Mpɛn pii no, Phytophthora capsici wɔ ahuhuro kɛse (28 kɔsi 32 °C) ne fɔmm mu. Botrytis cinerea (nsõ funu) nso betumi de aba wɔ awɔw ne fɔmm mu, anaa Colletotrichum capsici wɔ baabi a fɔmm dɔɔso.",
            effects = "Nhaban a ɛtew ntɛm ma awia ne yare foforɔ ka aba no. Aba a ɛtew ansa na ne berɛ aso tew nnɔbaeɛ so kɛse. Nhaban a ɛtew mpɛn pii ma dua no yɛ mmerɛw paa na ebetumi ama awu koraa.",
            prevention = "Yɛ nkoroo a ɛkorɔn na nsuo afiri mu yie. Ngu nsuo mfiri soro. Tew nnua dodow so na mframa afa mu. Mfa wo nsa nka nnua bere a fɔmm wɔ wɔn ho. Yi nneɛma a yare aka firi hɔ ntɛm na sɛe wɔn.",
            organicMitigation = "• Petepete Bordeaux mixture sɛ ɔbanbɔ nnansa 10 kɔsi 14 biara.\n• Petepete potassium silicate wɔ nhaban so na nhaban afasu ahoɔden nkɔ soro.\n• Yi nhaban a yare aka ne nwira firi hɔ ntɛm ara.\n• Ma nsuo mfiri asase mu yie denam nkoroo a ɛkorɔn ne abɔdeɛ nneɛma a wode gu mu so.\n• Fa Bacillus subtilis aduro (te sɛ Serenade) petepete wɔ nhaban so.",
            chemicalMitigation = "• Metalaxyl + Mancozeb: Ma yare a Phytophthora de ba; fa di dwuma sɛ ɔbanbɔ.\n• Copper hydroxide + Mancozeb: Ɛsa yare pii; fa di dwuma sɛ yare no pue a.\n• Iprodione (Rovral 500SC): Ɛyɛ adwuma tia Botrytis; fa di dwuma wɔ awɔw ne fɔmm mu.\n• Azoxystrobin: Ɛkɔ dua no mu; ɛsa nhaban nyarewa pii.\n• Fa aduro a ɛka ho ne nea ɛkɔ dua mu bom wɔ tank mu na ama ayɛ adwuma ntɛm."
        ),

        12 to DiseaseTranslation(
            localName = "Mako Nhwiren Kurukuruwa (mako nhaban mmobɔ yare)",
            description = "Mmoawa nketewa yare a ɛma nhaban bobɔ paa, ɛbɔ nkyerɛnkyerɛmu, na dua no nnyin. Ntutummɛ fitaa nkutoo na ɛsoa, na ɛtrɛw ntɛm wɔ mako mfuo mu titiriw wɔ ɔpɛ berɛ mu bere a ntutummɛ fitaa dɔɔso. Ayaresa biara nni hɔ; ɔbanbɔ ne ntutummɛ no a wɔbɛkum no ne adeɛ titiriw.",
            symptoms = "Nhaban bobɔ kɔ soro anaa fam paa na ɛbɔ nkyerɛnkyerɛmu. Nhaban a abobɔ no yɛ nketewa na ne nkyɛn yɛ akokɔsradeɛ. Nnua a yare aka no nnyin, wɔnnhwiren yie, na wɔso aba kakraa bi anaa wɔnso koraa. Dua no nyinaa te sɛ nea asɛe.",
            causes = "Chilli Leaf Curl Virus (ChiLCV) anaa Tomato Leaf Curl Virus (TLCV) a ntutummɛ fitaa (Bemisia tabaci) soa. Mmoawa nketewa no ntumi mfa asase, nnwinnadeɛ, anaa nsɔmu nkɔ — ɛhia ntutummɛ no.",
            effects = "Nnua a yare aka no nso aba — nnɔbaeɛ no sɛe koraa sɛ yare ka wɔn bere a wɔda so yɛ nketewa a. Mmoawa nketewa no trɛw ntɛm wɔ afuo no mu bere a ntutummɛ fitaa nantew. Nnɔbaeɛ no nyinaa betumi asɛe wɔ yare kɛse mu, titiriw wɔ ɔpɛ berɛ mu.",
            prevention = "Yɛ ɔdua wɔ asaawa a esi mmoawa kwan ase na woanya nnua a mmoawa nketewa nni wɔn ho. Ma baabi no nyɛ hɔ a ntutummɛ fitaa nni wɔ nnawɔtwe 3 kɔsi 4 a edi kan wɔ adua akyi. Tu nnua a yare aka no ntɛm na sɛe wɔn na mmoawa nketewa no tenabea so ntew. Nnua mako mmɛn ntoos, tawa, anaa wɔn abusuafoɔ.",
            organicMitigation = "• Fa nneɛma a ɛhyerɛn (dwetɛ anaa aluminium) kata asase so: Ɛma ntutummɛ fitaa ani si.\n• Fa akokɔsradeɛ afidie a ɛkyere nneɛma (30 wɔ hekta biara mu) si hɔ: Ɛkyere ntutummɛ fitaa na ɛkyerɛ wɔn dodow.\n• Petepete neem ngo (ɔha mu 3 kɔsi 4) ne mmoawa samina (ɔha mu 0.5) nnawɔtwe biara: Ɛkum ntutummɛ fitaa nketewa ne wɔn nkosua.\n• Dua marigold (Tagetes spp.) gu afuo no nkyɛn: Ɛpam ntutummɛ fitaa.\n• Tu nnua a yare aka wɔn nyinaa ntɛm ara na mmoawa nketewa no tenabea so ntew.",
            chemicalMitigation = "• Imidacloprid (Confidor 200SL): Gu asase mu anaa petepete wɔ nhaban so; ɛyɛ adwuma yie tia ntutummɛ fitaa; fa di dwuma sɛ wuhu wɔn a.\n• Thiamethoxam (Actara 25WG): Ɛkɔ dua no mu; sɛ wogu asase mu wɔ adua berɛ mu a, ɛbɔ dua no ho ban nnawɔtwe 4 kɔsi 6.\n• Spiromesifen (Oberon): Ɛyɛ adwuma tia ntutummɛ fitaa nketewa ne wɔn nkosua; sesa no ne neonicotinoids ntam.\n• Pyriproxyfen (Admiral): Esi ntutummɛ fitaa nyin kwan.\n• Hyɛ no nsow: Aduro biara nsa mmoawa nketewa yare sɛ ɛba a — fa w'ahoɔden nyinaa si ntutummɛ no kum so."
        ),

        13 to DiseaseTranslation(
            localName = "Mako Nhwiren Mfirimiri (mako nhaban nhwɛso yare)",
            description = "Mmoawa nketewa yare a ɛma ahabammono a ɛhyerɛn, ahabammono tuntum ne akokɔsradeɛ di afra wɔ nhaban so, na mpɛn pii no nhaban sɛe na dua no nnyin. Mmoawa aphid ne nsɔmu na ɛde trɛw, enti ɛtrɛw ntɛm wɔ afuo a wɔhwɛ so yie mu.",
            symptoms = "Mmeaeɛ a ɛsesa wɔ ahabammono a ɛhyerɛn, akokɔsradeɛ ne ahabammono tuntum ntam (nhwɛso) wɔ nhaban ani. Nhaban betumi ayɛ hiahiaa, abɔ nkyerɛnkyerɛmu, anaa asɛe. Mman foforɔ nnyin na ɛsɛe. Nnua so aba nketewa a mpɛn pii no asɛe na ne boɔ nsõ.",
            causes = "Tobacco Mosaic Virus (TMV), Cucumber Mosaic Virus (CMV), anaa Pepper Mosaic Virus (PepMV). TMV fa nsɔmu (nsa, nnwinnadeɛ) ne aba a yare aka so trɛw. CMV deɛ, mmoawa aphid (Myzus persicae, Aphis gossypii) na ɛde trɛw mpɛn pii.",
            effects = "Nnɔbaeɛ tew ɔha mu 30 kɔsi 70 wɔ nnua a yare aka wɔn so. Aba nsi yie, aba nketewa a asɛe na ne boɔ nsõ wɔ gua so. Ayaresa biara nni hɔ. Mmoawa nketewa a aphid soa betumi aka afuo no nyinaa ntɛm sɛ aphid dɔɔso a.",
            prevention = "Dua mako ahorow a ɛko tia saa yare yi (wonya wɔ IITA ne CSIR-SARI hɔ wɔ Ghana). Kum aphid — wɔn na wɔde trɛw kɛse. Hohoro nnwinnadeɛ nyinaa ho wɔ bleach ɔha mu 10 anaa nsa ɔha mu 70 mu ansa na woayɛ adwuma ne n'akyi. Hohoro wo nsa ansa na woaso nnua mu. Nnom tawa mmɛn nnua no (TMV firibea).",
            organicMitigation = "• Petepete neem ngo (ɔha mu 2) nnawɔtwe biara tia aphid — ɛyɛ adwuma tia mpanyimfoɔ ne nketewa nyinaa.\n• Dwetɛ a ɛhyerɛn a wode kata asase so: Esi aphid kwan sɛ wɔbɛsi.\n• Tu nnua a yare aka no ntɛm ara — fa hyɛ kotoku mu, yi firi afuo no mu, na sɛe wɔn.\n• Petepete nufusuo a wɔayi ngo afiri mu a wɔde nsuo afra (nufusuo 1 : nsuo 9) wɔ nnwinnadeɛ ne nsa so — ɛsɛe TMV.\n• Dua coriander, dill, anaa fennel gu ho na aphid atamfoɔ (ladybird, lacewing) mmra.",
            chemicalMitigation = "• Imidacloprid (Confidor) anaa Acetamiprid (Mospilan): Mmoawa aduro a ɛkɔ dua mu tia aphid; fa di dwuma sɛ wuhu aphid a edi kan a.\n• Malathion (Malathion 57 EC): Aduro a ɛka ho a ɛyɛ adwuma tia aphid; fa kum wɔn ntɛm.\n• Aboɔ ngo (horticultural oil): Ɛtew aphid tumi a ɛde CMV trɛw no so.\n• Pymetrozine (Chess WG): Aphid aduro a ɛnsɛe mmoawa pa; ɛne neonicotinoids kɔ yie.\n• Aduro biara nsa mmoawa nketewa yare — akwan nyinaa nsi yare no kwan."
        ),

        14 to DiseaseTranslation(
            localName = "Mako Nhwiren Ponko Ketewa (mako nkeka nketewa yare)",
            description = "Mmoawa yare a ɛyɛ nkeka nketewa pii wɔ mako nhaban so, na ɛma nhaban tew nkakrankakra. Mmoawa yare no nyin wɔ ahuhuro ne fɔmm mu. Ɛwom sɛ ano nyɛ den te sɛ nhaban wuo yare de, nanso yare a ɛba mpɛn pii wɔ mfe no mu tew nnɔbaeɛ so kɛse.",
            symptoms = "Nkeka nketewa pii a ɛyɛ kurukuruwa (milimita 2 kɔsi 5) a ne nkyɛn yɛ birebire tuntum na emu yɛ nsõ-fitaa. Wuhu nsonsonoeɛ tuntum nketewa (pycnidia — baabi a mmoawa no nsɛso wɔ) wɔ mfimfini sɛ wode adeɛ a ɛma adeɛ yɛ kɛse hwɛ a. Nhaban a yare aka no dan akokɔsradeɛ na ɛtew ansa na ne berɛ aso.",
            causes = "Mmoawa Septoria capsici. Ɛtena nnua nwira a yare aka ne asase mu. Osutɔ mpete ne nsuo a wɔgu firi soro de ne nsɛso kɔ. Ahuhuro (20 kɔsi 25 °C), fɔmm kɛse ne nsuo a ɛwɔ nhaban so boa yare no.",
            effects = "Nhaban a ɛtew firi ase kɔ soro tew aduane a dua no yɛ ne aba so. Nnɔbaeɛ hwere a ɛyɛ ɔha mu 25 kɔsi 50 betumi aba wɔ mfuo a wɔnhwɛ so mu wɔ osutɔ berɛ mu. Nhaban a ɛtew mpɛn pii ma dua no yɛ mmerɛw na berɛ a ɛso aba no tiaa.",
            prevention = "Fa abɔdeɛ nneɛma a mu yɛ duru kata dua no ase na asase mpete nkɔ nhaban a ɛwɔ ase so. Ngu nsuo mfiri soro — fa nsuo a ɛsensen di dwuma. Ma kwan a ɛboro sentimita 60 nna hɔ na mframa afa mu. Yi nwira a yare aka firi hɔ wɔ otwa akyi na sɛe. Sesa nnɔbaeɛ mfe 2 kɔsi 3.",
            organicMitigation = "• Fa nneɛma kata asase so yie (nwura, ɛmo ho ntoma) twa nnua no ho hyia na asase mpete mfa yare nsɛso nkɔ.\n• Petepete kɔbere aduro (Bordeaux mixture) sɛ ɔbanbɔ nnansa 10 kɔsi 14 biara.\n• Yi nhaban a ɛwɔ ase a yare aka no firi hɔ sɛ wohu a na yare no trɛw ase brɛ.\n• Petepete neem ngo ne bicarbonate nkabom na ama mmoawa yare no nnyin.\n• Ma kwan pa nna hɔ na twitwa mman a ɛwɔ ase na mframa afa mu.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Ɛbɔ ho ban; fa di dwuma nnansa 7 kɔsi 10 biara wɔ fɔmm berɛ mu.\n• Chlorothalonil (Bravo 500): Aduro a ɛka ho a ɛyɛ adwuma; fa di dwuma nnansa 10 kɔsi 14 biara.\n• Tebuconazole (Folicur 250EW): Ɛkɔ dua no mu; ɛbɔ ho ban na ɛsa yare nso; fa di dwuma sɛ yare no pue a.\n• Azoxystrobin: Ɛkɔ dua no mu; ɛyɛ adwuma yie; fa di dwuma nnansa 14 biara.\n• Sesa aduro abusua ahorow wɔ nsa 2 kɔsi 3 biara akyi na yare no antumi angyina ano."
        ),

        // ── NTOOS ─────────────────────────────────────────────────────────────

        15 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ponko (ntoos nhaban nkeka yare)",
            description = "Mmoawa nketewa yare a ɛsɛe adeɛ. Ɛka nhaban, nnua ne aba wɔ ahuhuro ne fɔmm mu. Ɛbu so wɔ Ghana ntoos mmeaeɛ wɔ osutɔ berɛ mu. Nkeka a ɛba aba so tew ne boɔ ne berɛ a ɛtumi tena so kɛse, na ɛde sika hwere kɛse ba.",
            symptoms = "Nkeka nketewa birebire tuntum, a ɛyɛ kurukuruwa anaa wɔn su nni hɔ (milimita 2 kɔsi 5), a akokɔsradeɛ atwa ho ahyia wɔ nhaban so. Nkeka no betumi aka abom ayɛ mmeaeɛ akɛseɛ a awu. Nnua nya nkeka tuntum a ɛpagya na ɛware. Aba mono nya nkeka birebire tuntum a ɛpagya te sɛ ɔhonam ani kurow, na ɛtena hɔ kosi sɛ aba no bɛbere.",
            causes = "Mmoawa nketewa Xanthomonas perforans (T3/T4), X. vesicatoria, anaa wɔn abusuafoɔ. Ɛfa osutɔ mpete, bosuo, nsuo a wɔgu firi soro, nnwinnadeɛ a yare aka, ne aba anaa nnua a yare aka so trɛw. Yare no hia nsuo wɔ nhaban ani simma 30 pɛ.",
            effects = "Nhaban a ɛtew kɛse ma awia ka aba no. Nkeka a ɛba aba so tew ne boɔ wɔ gua so ɔha mu 50 kɔsi 80. Nnɔbaeɛ hwere betumi adu ɔha mu 50 wɔ mfe a yare no bu so mu. Wɔpo ntoos a wɔde kɔ amanɔne esiane ne ho dɛm nti. Ntoos a yare aka no ntumi ntena hɔ nkyɛ wɔ otwa akyi.",
            prevention = "Fa aba ne nnua a wɔasɔ ahwɛ sɛ yare nni wɔn ho nkutoo di dwuma. Ngu nsuo mfiri soro — fa nsuo a ɛsensen di dwuma. Sesa nnɔbaeɛ mfe 3 na fa nnɔbaeɛ a ɛnyɛ ntoos abusua di akyi. Tew adwuma a woyɛ wɔ afuo mu bere a fɔmm wɔ nnua no ho so. Hohoro nnwinnadeɛ ho wɔ nnidisoɔ ntam wɔ bleach ɔha mu 10 mu.",
            organicMitigation = "• Petepete Bordeaux mixture (kɔbere sulfate ɔha mu 1 + aboɔ nkyene ɔha mu 0.5) nnansa 7 kɔsi 10 biara wɔ fɔmm berɛ mu.\n• Petepete neem ngo ne castile samina nkabom sɛ ɔbanbɔ foforɔ wɔ kɔbere petepete mmienu ntam.\n• Fa nneɛma kata dua no ase yie na asase mpete (yare firibea) nkɔ so.\n• Yi nhaban ne nwira a yare aka firi hɔ daa na sɛe wɔn.\n• Compost a wode gu asase mu ma asase no nkwa yɛ pa na dua no ahoɔden kɔ soro.",
            chemicalMitigation = "• Copper hydroxide (Kocide 3000 anaa Funguran OH): Fa di dwuma nnansa 7 kɔsi 10 biara; eyi na wɔde di dwuma kɛse.\n• Copper oxychloride + Mancozeb (Cuprosan anaa Curzate): Nkabom a ɛyɛ adwuma ma mmoawa nketewa ne mmoawa yare.\n• Streptomycin sulfate (Agri-Mycin): Fa di dwuma sesa ne kɔbere ntam; mma ɛmmoro nsa 2 kɔsi 3 na yare no antumi angyina ano.\n• Kasugamycin (Kasumin): Aduro foforɔ a ɛyɛ adwuma tia Xanthomonas.\n• Mfa kɔbere nni dwuma wɔ ahuhuro ne awia denden mu na nhaban anhyew."
        ),

        16 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ohow Ntem (ntoos nhaban hyew ntɛm)",
            description = "Ntoos mmoawa nyarewa a ɛbu so sen biara wɔ wiase mu baako, na ɛbu so paa wɔ Ghana. Nkeka nhwɛso a ɛte sɛ nea wɔtow tuo gu so wɔ nhaban dedaw a ɛwɔ ase so ne ne sɛnkyerɛnne. Yare a ano yɛ den betumi ama nhaban nyinaa atew, na atew nnɔbaeɛ so ɔha mu 50 kɔsi 80.",
            symptoms = "Nkeka tuntum (milimita 5 kɔsi 15) a nkyerɛnkyerɛmu atwa ho ahyia te sɛ nea wɔtow tuo gu so, kane wɔ nhaban dedaw a ɛwɔ ase so. Akokɔsradeɛ betumi atwa nkeka no ho ahyia. Bere a yare no reforo kɔ soro no, nhaban dan akokɔsradeɛ na ɛtew ansa na ne berɛ aso. Nnua betumi anya nkeka atenten tuntum a ɛkɔ mu (kɔn porɔw wɔ nnua nketewa mu).",
            causes = "Mmoawa Alternaria solani (ne A. alternata). Ɛwɔ asase mu ne aba mu nyinaa. Ɛtena nnɔbaeɛ nwira mu. Ahuhuro (24 kɔsi 29 °C), fɔmm kɛse, ne nsuo ne ɔpɛ a ɛsesa boa no. Osutɔ mpete ne mframa de ne nsɛso kɔ.",
            effects = "Nhaban a ɛtew firi ase kɔ soro, na ɛtew aduane a dua no yɛ so kɛse. Nhaban a ɛtew kɛse ma awia ka aba no na ɛtew dɛdɛ a ɛyɛ so. Nnɔbaeɛ hwere a ɛyɛ ɔha mu 50 kɔsi 80 betumi aba wɔ mfe a ano yɛ den mu. Nnua a wɔayɛ mmerɛw no nya yare foforɔ ntɛm.",
            prevention = "Twitwa nhaban a ɛwɔ ase a ɛka asase no na asase mpete nkɔ so. Fa nneɛma a mu yɛ duru (sare anaa nwura) kata dua no ase. Ma kwan a ɛyɛ sentimita 60 pɛ nna nnua ntam. Fa dua anaa dadeɛ si nnua no ho na nhaban anka asase. Sesa nnɔbaeɛ mfe 3 na fa nnɔbaeɛ a ɛnyɛ ntoos abusua di akyi.",
            organicMitigation = "• Fa sare anaa nwura a awo (mu tenten sentimita 8 kɔsi 10) kata asase so na asase mpete nkɔ so — ɛno ne yare no kwan kɛse.\n• Twitwa nhaban a ɛwɔ ase a yare aka no ntɛm ara na sɛe wɔn.\n• Petepete kɔbere sulfate (Bordeaux mixture) nnansa 10 biara sɛ ɔbanbɔ.\n• Petepete neem ngo (ɔha mu 2) ma yare nketewa a ɛba ntɛm.\n• Petepete calcium wɔ nhaban so (calcium nitrate anaa calcium chloride ɔha mu 0.5) na nhaban afasu ahoɔden nkɔ soro na yare no trɛw ase brɛ.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500 anaa Daconil): Eyi na wɔde di dwuma kɛse; fa di dwuma nnansa 7 kɔsi 10 biara sɛ ɔbanbɔ.\n• Mancozeb (Dithane M-45): Aduro a ɛbɔ ho ban yie; fa di dwuma sesa ne Chlorothalonil ntam.\n• Azoxystrobin (Amistar): Ɛkɔ dua no mu; fa di dwuma nnansa 14 biara; ɛyɛ papa wɔ nhyehyɛeɛ nyinaa mu.\n• Difenoconazole (Score 250EC): DMI aduro; fa di dwuma sɛ wuhu yare no a edi kan a.\n• Boscalid + Pyraclostrobin (Signum): SDHI ne strobilurin nkabom pa ma ɔbanbɔ wɔ mfe no nyinaa mu."
        ),

        17 to DiseaseTranslation(
            localName = "Ntomato Kobuo (ntoos nwuo yare)",
            description = "Mmoawa yare a ɛwɔ asase mu na ɛsɛe adeɛ paa. Esi dua no nsuo akwan kwan, enti nsuo ne aduane ntumi nkɔ dua no fa horow mu. Sɛ asase no nya yare no a, ɛtena hɔ daa. Ɛyɛ ɔhaw kɛse ma ntoos kuadwuma wɔ Ghana kwaeɛ mmeaeɛ a asase ahuhuro fata no.",
            symptoms = "Nhaban dan akokɔsradeɛ, na mpɛn pii no ɛfiri dua anaa ɔbaa baako so. Nhaban wu wɔ awia ahuhuro berɛ mu. Sɛ wogu nsuo so mpo a nwuo no nnyɛ yie. Nsuo akwan no ahosuo dan birebire kɔsi kɔkɔɔ, na wuhu sɛ wotwa dua no wɔ ase a.",
            causes = "Mmoawa Fusarium oxysporum f. sp. lycopersici (abusua 1, 2 ne 3) a ɛwɔ asase mu. Ɛtena asase mu daa sɛ chlamydospores (mfe 20 ne nea ɛboro so). Asase a ahuhuro wɔ mu (25 kɔsi 30 °C) ne asase a nsuonwono wɔ mu (pH a ɛba 5.5 ase) boa no. Ɛfa nhini akuru anaa abɔdeɛ akwan so kɔ mu.",
            effects = "Dua no wu wɔ nna anaa nnawɔtwe kakraa bi akyi sɛ sɛnkyerɛnne no pue a. Nnɔbaeɛ nyinaa betumi asɛe wɔ mfuo a yare aka no denneennen mu. Asase no kura yare no mfe pii — nnɔbaeɛ a wobedua wɔ hɔ daakye wɔ asiane mu. Ayaresa biara nni hɔ. Eyi na ɛma ntoos akuafoɔ gyaw wɔn mfuo hɔ.",
            prevention = "Dua aba a ɛko tia Fusarium nkutoo (hwehwɛ F, FF anaa FFF wɔ aba kotoku so — ɛkyerɛ ahoɔden tia abusua 1, 2 ne 3). Ma asase no pH nyɛ 6.5 kɔsi 7.0 denam aboɔ nkyene so. Ma nsuo mfiri asase mu yie. Fa nnua nketewa firi ɔdua a wɔasɔ ahwɛ nkutoo hɔ. Nnua ntoos wɔ asase a yare aka mu kosi mfe 5 kɔsi 7.",
            organicMitigation = "• Asase hyew wɔ awia mu: Gu nsuo asase no so yie, afei fa plastik a ani da hɔ a ɛyɛ micron 50 kata so nnawɔtwe 4 kɔsi 6 wɔ ahuhuro berɛ mu — ɛtew Fusarium so ɔha mu 90 wɔ sentimita 15 a edi kan mu.\n• Trichoderma harzianum (te sɛ Trichomax, Biomax-T): Fa ka dua tokuro ho anaa gu asase mu sɛ nsuo; ɛne Fusarium di akan na ɛsɛe no.\n• Mmoawa pa (Glomus intraradices): Fa gu nhini ho wɔ adua berɛ mu; ɛma aduane a wɔgye ne nhini ahoɔden kɔ soro.\n• Neem aba a woayam: Fa gram 200 ka dua tokuro ho ma dua biara.\n• Compost a wode gu mu: Ɛma asase no nkwa yɛ pa, na ɛno si Fusarium kwan.",
            chemicalMitigation = "• Carbendazim (Bavistin 50WP): Gu asase mu wɔ adua berɛ mu sɛ ɔbanbɔ nkutoo.\n• Metalaxyl + Thiram: Aba aduro a ɛbɔ nnua nketewa nhini ho ban wɔ fifi berɛ mu.\n• Fludioxonil (Maxim): Aba aduro a ɛyɛ adwuma yie tia Fusarium kɔn ne nhini porɔw.\n• Metam sodium (asase aduro): Wɔde di dwuma wɔ tebea a ano yɛ den mu ansa na wɔadua — ɛhia obi a wanim adwuma no.\n• Nea ɛho hia: Aduro biara a ɛkɔ dua mu nsa Fusarium nwuo yare sɛ ɛkɔ nsuo akwan no mu dedaw a."
        ),

        18 to DiseaseTranslation(
            localName = "Ntomato Pa (ntoos a ɛwɔ ahoɔden)",
            description = "Ntoos dua yi wɔ ahoɔden pa, ɛrenyin yie na tumi wɔ so sɛ ɛbɛso aba pii. Ntoos a ɛwɔ ahoɔden a wɔhwɛ so yie so aba pii a ɛyɛ pa, na ɛboa okuafoɔ mfaso ne aduane wɔ Ghana.",
            symptoms = "Nhaban ahabammono a mu yɛ tuntum pɛ, nkeka, ntenten, akokɔsradeɛ anaa nwuo nni ho. Nnua a ɛyɛ den a ɛso dua no duru. Nhwiren akokɔsradeɛ a ɛte sɛ nsoromma. Aba mono a ho yɛ tromtrom na n'ahosuo yɛ pɛ, a ɛdan kɔkɔɔ yie sɛ ɛbere a.",
            causes = "Asase pH a ɛfata (6.0 kɔsi 6.8), nsuo a wogu so daa pɛ (milimita 25 kɔsi 40 wɔ nnawɔtwe mu), NPK sumina a ɛkari pɛ ne aduane nketewa, kwan a ɛda nnua ntam, ne mmoawa ne nyarewa a wɔhwɛ so daa.",
            effects = "Aba pii, aba a ɛso, dɛdɛ pa, ahosuo pa ne berɛ tenten a ɛtumi tena hɔ. Nnua a ɛyɛ den gyina ɔhaw a ɛtaa ba ano. Nnɔbaeɛ a ɛba daa ma okuafoɔ nya mfaso na aduane wɔ fie.",
            prevention = "Kɔ so yɛ deɛ woreyɛ no. Hwɛ nnua no so mprenu wɔ nnawɔtwe mu na woahu yare anaa mmoawa sɛnkyerɛnne a edi kan. Hwɛ nnua anaa dadeɛ a wode si so bere a dua no renyin. Twitwa mman a ɛnso aba na ahoɔden no nkɔ aba no so. Twerɛ adua, nneɛma a wode di dwuma, ne nea wonya gu hɔ.",
            organicMitigation = "• Fa abɔdeɛ nneɛma a aporɔw yie (kilo 3 kɔsi 5 ma dua biara) gu mu wɔ adua berɛ mu.\n• Fa sare anaa nwura (mu tenten sentimita 10) kata asase so na nsuo ntena mu na nwura anfifi.\n• Fa mpampuro anaa dadeɛ afidie si nnua no ho na dua no ammu na mframa afa mu.\n• Dua basil (ɛpam thrips ne aphid) ne marigold (ɛpam nematode ne ntutummɛ fitaa) gu ho.\n• Petepete nnua nsuo a akaw anaa compost nsuo wɔ nhaban so na dua no ahoɔden nkɔ soro.",
            chemicalMitigation = "• Fa NPK 15-15-15 di dwuma wɔ adua berɛ mu, afei sesa kɔ sumina a nitrogen sua wɔ mu (te sɛ 8-24-24) wɔ aba berɛ mu.\n• Petepete calcium nitrate (ɔha mu 0.5) wɔ nhaban so wɔ nhwiren berɛ mu na aba no ase amporɔw.\n• Petepete kɔbere (Bordeaux mixture) sɛ ɔbanbɔ wɔ osutɔ berɛ mfiaseɛ.\n• Mmoawa aduro nhyehyɛeɛ a ɛbɔ ho ban ma ntutummɛ fitaa ne aphid (fa Imidacloprid ka aba ho wɔ ɔdua berɛ mu).\n• Fa potassium sulfate di dwuma bere a aba no renyin na ne su ne n'ahoɔden nkɔ soro."
        ),

        19 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Kwanee (ntoos nhaban wuo yare)",
            description = "Ntoos yare a wosuro no sen biara wɔ wiase — yare koro no ara na ɛde Ireland ɔkɔm kɛse no bae wɔ mfe 1840 mu. Ebetumi asɛe ntoos mfuo nyinaa wɔ nnansa 7 kɔsi 10 mu wɔ awɔw ne fɔmm mu. Ɛsɛe ntoos kuadwuma wɔ Ghana osutɔ mmerɛ mu. Sɛ wuhu no a, ɛsɛ sɛ woyɛ ntɛm ara.",
            symptoms = "Nkeka akɛseɛ (sentimita 2 kɔsi 3) a ɛyɛ tuntum, nsõ-birebire, te sɛ wɔasra ngo, wɔ nhaban ne nnua so. Sɛ fɔmm dɔɔso a, mmoawa fitaa a ɛyɛ fufuo pue wɔ nhaban ase. Nkeka birebire tuntum a ɛyɛ den wɔ aba so. Nnua a yare aka hwe ase. Mfuo nyinaa betumi ayɛ sɛ ogya ahye wɔ nna kakraa bi mu.",
            causes = "Phytophthora infestans. Mframa de ne nsɛso tu kwan kilomita 50 ne nea ɛboro so. Anadwo awɔw (10 kɔsi 20 °C) ne fɔmm kɛse fata yare no sen biara. Dua baako a yare aka anaa dwaben afuo a ɛbɛn a yare aka betumi ahyɛ yare no ase.",
            effects = "Nnɔbaeɛ no nyinaa sɛe wɔ nnansa 7 kɔsi 10 mu sɛ tebea no fata yare no a. Sɛ yare no ka aba no a, wontumi ntɔn nnɔbaeɛ no nyinaa. Sika hwere kɛse — yare yi a ɛbɛba pɛnkoro betumi asɛe akuafoɔ mpɔtam nyinaa. Ɛyɛ nnua nyarewa a ɛsɛe adeɛ sen biara wɔ wiase.",
            prevention = "Dua aba a ɛko tia yare no (te sɛ Ferline, Legend, Defiant) sɛ ɛwɔ hɔ a. Di wim nsɛm akyi — anadwo awɔw ne fɔmm kɛse kyerɛ asiane kɛse. Fa aduro di dwuma ansa na sɛnkyerɛnne a edi kan apue wɔ asiane berɛ mu. Ma afuo no nyɛ wosee — ngu nsuo mfiri soro. Hwɛ afuo no so da biara wɔ awɔw ne osutɔ mmerɛ mu.",
            organicMitigation = "• Bordeaux mixture (kɔbere sulfate ɔha mu 3 kɔsi 4 + aboɔ nkyene ɔha mu 3): Petepete nnansa 5 kɔsi 7 biara wɔ awɔw ne fɔmm mu — eyi ne abɔdeɛ ɔbanbɔ titiriw.\n• Yi nnua fa a yare aka NYINAA firi hɔ ntɛm ara na sɛe — fa hyɛ kotoku mu, yi firi afuo no mu, mfa nyɛ compost.\n• Ma nsuo mfiri afuo no mu yie na nnua wɔ mmeaeɛ a ɛba fam.\n• Copper octanoate (Cueva): Kɔbere aduro a wɔapene so ma abɔdeɛ kuadwuma; fa di dwuma nnansa 5 biara wɔ asiane berɛ mu.\n• Ngu nsuo mfiri soro wɔ awɔw mmerɛ mu — fa nsuo a ɛsensen nkutoo di dwuma.",
            chemicalMitigation = "• Metalaxyl + Mancozeb (Ridomil Gold MZ 68WG): Aduro a edi kan; fa di dwuma nnansa 7 biara sɛ ɔbanbɔ wɔ awɔw ne fɔmm mu — ntwɛn sɛnkyerɛnne.\n• Cymoxanil + Famoxadone (Equation Pro): Nkabom a ɛkɔ dua mu na ɛbɔ ho ban nso; fa di dwuma nnansa 5 kɔsi 7 biara.\n• Dimethomorph (Forum): Ɛkɔ dua no mu; ɛyɛ adwuma wɔ yare a ɛba ntɛm akyi; sesa no ne Ridomil ntam.\n• Fluopicolide + Propamocarb (Infinito): Ɛkɔ dua no mu yie; fa di dwuma nnansa 7 kɔsi 10 biara.\n• Sesa aduro akuo nyinaa wɔ nsa 2 biara akyi, ɛfiri sɛ Phytophthora gyina aduro ano ntɛm paa."
        ),

        20 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Kurukuruwa (ntoos nhaban mmobɔ yare)",
            description = "Wɔfrɛ no nso ntoos nhaban akokɔsradeɛ mmobɔ (TYLCV). Saa mmoawa nketewa yare a ntutummɛ fitaa soa yi yɛ ntoos nyarewa a ɛsɛe adeɛ sen biara wɔ wiase mu baako. Ntutummɛ fitaa Bemisia tabaci nkutoo na ɛsoa. Ɛsɛe adeɛ paa wɔ Ghana ɔpɛ berɛ mu bere a ntutummɛ fitaa dɔɔso.",
            symptoms = "Nhaban bobɔ kɔ soro ne mu paa, na ne nkyɛn dan akokɔsradeɛ. Nhaban a yare aka no yɛ nketewa, mu yɛ duru na ɛyɛ den. Dua no fa a ɛda ntam no tiaa enti dua no yɛ sɛ nwura ketewa. Ɛnnyin koraa — dua no ntra sentimita 30. Ɛnso aba koraa; sɛ ɛso bi a, ɛyɛ nketewa a n'ahosuo nyɛ fɛ.",
            causes = "Tomato Yellow Leaf Curl Virus (TYLCV), Begomovirus a Bemisia tabaci nkutoo na ɛsoa. Ntutummɛ fitaa baako a yare wɔ ne ho betumi ama dua no anya yare wɔ simma kakraa bi mu. Ɔkwan foforɔ biara nni hɔ a ɛfa so — ɛnyɛ asase anaa nnwinnadeɛ so.",
            effects = "Nnɔbaeɛ no sɛe koraa sɛ nnua no nya yare no wɔ nnawɔtwe 3 kɔsi 4 a edi kan wɔ adua akyi a. Nea ɛnya yare akyire yi no betumi aso ɔha mu 20 kɔsi 30 pɛ. Mmoawa nketewa no trɛw ntɛm — ntutummɛ fitaa kuo baako betumi aka afuo no nyinaa wɔ nnawɔtwe 2 mu. Sika hwere kɛse, titiriw wɔ ɔpɛ berɛ ntoos kuadwuma mu.",
            prevention = "Yɛ ɔdua wɔ asaawa a mu yɛ ketewaa (mesh 50) ase na woanya nnua a ntutummɛ fitaa nni wɔn ho. Yɛ afuo foforɔ no akyirikyiri firi ntoos mfuo a yare aka ho. Tu ntoos a efifi n'ankasa nyinaa na sɛe, ɛfiri sɛ ɛhɔ na mmoawa nketewa no tena. Fa akokɔsradeɛ afidie a ɛkyere nneɛma hwɛ ntutummɛ fitaa dodow so firi adua berɛ mu.",
            organicMitigation = "• Asaawa a mu yɛ ketewaa (mesh 50) a wode kata aba mpa so: Esi ntutummɛ fitaa kwan sɛ wɔbɛba nnua nketewa ho wɔ nyin berɛ a ɛho hia no mu.\n• Dwetɛ anaa aluminium a ɛhyerɛn a wode kata asase so: Ɛpam ntutummɛ fitaa; ɛyɛ adwuma yie wɔ mfe no mfiaseɛ.\n• Akokɔsradeɛ afidie a ɛkyere nneɛma (20 kɔsi 30 wɔ hekta biara mu): Ɛkyere ntutummɛ fitaa mpanyimfoɔ na ɛkyerɛ wɔn dodow.\n• Petepete neem ngo (ɔha mu 3 kɔsi 4) ne mmoawa samina nnawɔtwe biara: Ɛsa ntutummɛ fitaa nketewa ne wɔn nkosua.\n• Tu nnua a yare aka nyinaa ntɛm ara na sɛe — wɔyɛ mmoawa nketewa no firibea daa ma afuo no nyinaa.",
            chemicalMitigation = "• Imidacloprid (Confidor 200SL) a wogu asase mu wɔ adua berɛ mu: Ɛbɔ dua no ho ban nnawɔtwe 4 kɔsi 6 — eyi ne ɔbanbɔ ɔkwan pa sen biara wɔ mfiaseɛ.\n• Thiamethoxam (Actara 25WG) sɛ aba aduro anaa gu asase mu: Ɛsa ntutummɛ fitaa yie.\n• Spiromesifen (Oberon): Ɛkɔ ntutummɛ fitaa nkosua ne nketewa so; sesa no ne neonicotinoids ntam na wɔantumi angyina ano.\n• Buprofezin (Applaud): Esi ntutummɛ fitaa honam ani sesa kwan; fa di dwuma sesa mu.\n• Nea ɛho hia: Mmoawa nketewa yare aduro biara nni hɔ — ɛsɛ sɛ mmɔdenbɔ nyinaa kɔ ntutummɛ no so ansa na wɔde yare no aba."
        ),

        21 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Mfirimiri (ntoos nhaban nhwɛso yare)",
            description = "Mmoawa nketewa a ɛyɛ den a ɛfa nsɔmu so trɛw, na ɛma nhwɛso ne mpumpunnya ba ntoos nhaban so. Tobacco Mosaic Virus (TMV) yɛ nnua nyarewa a wɔasua ho ade sen biara mu baako — ɛyɛ den paa na ɛtumi tena tawa a awo mu mfe pii. Nnwinnadeɛ ne nsa a yare wɔ ho ne akwan titiriw a ɛfa so trɛw wɔ afuo a wɔhwɛ so mu.",
            symptoms = "Mmeaeɛ a ɛsesa wɔ ahabammono a ɛhyerɛn ne ahabammono tuntum ntam wɔ nhaban so (nhwɛso). Nhaban betumi asɛe, ayɛ hiahiaa, anaa ayɛ te sɛ ahoma. Nhaban ani betumi ayɛ mpumpunnya. Ntenten birebire anaa tuntum a ɛkɔ mu wɔ nnua so. Aba betumi akyerɛ nhwɛso akokɔsradeɛ anaa birebire wɔ mu.",
            causes = "Tobacco Mosaic Virus (TMV) anaa Tomato Mosaic Virus (ToMV). Ɛfa nsɔmu so trɛw mpɛn pii: nsa, nnwinnadeɛ, ntadeɛ, ne mmoawa a wɔnom nneɛma. TMV yɛ den paa — ɛtena tawa a awo mu, asase mu, ne nneɛma ani abosome kɔsi mfe pii. Aba a yare aka betumi ade atrɛw.",
            effects = "Nnɔbaeɛ tew ɔha mu 10 kɔsi 35 esiane aba a ɛnsi yie ne aba nketewa a ne su nyɛ pa nti. Wontumi ntɔn aba a nhwɛso wɔ so. TMV tena hɔ kyɛ paa — afuo betumi akura yare no mfe pii. Dua a yare aka biara nsa. Ɛtrɛw ntɛm baabi a wɔadua nnua bebree abom.",
            prevention = "Dua aba a ɛko tia mmoawa nketewa no nkutoo (Tm-2 ahoɔden — ɛwɔ ntoos ahorow foforɔ dodow no ara mu). Hohoro nnwinnadeɛ nyinaa ho wɔ bleach ɔha mu 10 anaa nsa ɔha mu 70 mu ansa na wode adi dwuma ne wɔ nnua ntam. Hohoro wo nsa ho yie wɔ samina mu ansa na woaso nnua mu. Nnom tawa na mfa wo nsa nka tawa nneɛma mmɛn ntoos da (TMV firibea). Tu nnua a yare aka no ntɛm.",
            organicMitigation = "• Dua aba a ɛko tia TMV/ToMV (Tm-2 anaa Tm-2² ahoɔden) — eyi nkutoo ne ɔbanbɔ pa sen biara.\n• Petepete nufusuo a wɔayi ngo afiri mu (1:10 wɔ nsuo mu): Ɛsɛe mmoawa nketewa no nneɛma wɔ nnua ne nnwinnadeɛ ani; petepete wɔ nnwinnadeɛ ne nsa so ansa na woayɛ adwuma.\n• Tu nnua a yare aka no ntɛm ara na sɛe — mfa nyɛ compost; fa hyɛ kotoku mu na hyew.\n• Fa nsuo a ɛyɛ hyew (50 °C simma 30) yɛ aba no na mmoawa nketewa a ɛwɔ aba mu no afi hɔ ansa na woadua.\n• Mfa nitrogen pii nni dwuma, ɛfiri sɛ ɛma dua no yɛ mmerɛw na ɛnya yare no ntɛm.",
            chemicalMitigation = "• Aduro biara nsa mmoawa nketewa yare wɔ nnua mu.\n• Imidacloprid anaa Acetamiprid: Ɛsa mmoawa a wɔnom nneɛma (aphid, thrips) a wobetumi de yare no ahyɛ dua no mu bere a wɔredidi.\n• Nnua ahoɔden nnuro (Acibenzolar-S-methyl / Actigard): Ɛma dua no ankasa ahoɔden sɔre; ɛbetumi atew sɛnkyerɛnne no ano den so wɔ mmere bi mu.\n• Aboɔ ngo (horticultural oil): Sɛ wode petepete nhaban so a, ɛbetumi atew nsɔmu trɛw so.\n• Ɛsɛ sɛ adwuma no nyinaa gyina ahotew, aba a ɛko tia yare no, ne nnua a yare aka a wobetu so."
        ),

        22 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ponko Ketewa (ntoos nkeka nketewa yare)",
            description = "Ntoos mmoawa nyarewa a ɛbu so sen biara mu baako, a ɛyɛ nkeka pii na ɛma nhaban tew nkakrankakra firi ase kɔ soro. Ɛtrɛw paa wɔ Ghana osutɔ berɛ mu. Ɛwom sɛ ɛntaa nkum nnua koraa de, nanso nhaban a ɛtew mpɛn pii tew nnɔbaeɛ ne aba su so kɛse.",
            symptoms = "Nkeka nketewa pii a ɛyɛ kurukuruwa (milimita 2 kɔsi 5) a ne nkyɛn yɛ birebire tuntum pefee na emu yɛ fitaa kɔsi nsõ wɔ nhaban so. Wuhu nsonsonoeɛ tuntum nketewa (pycnidia — baabi a mmoawa nsɛso wɔ) wɔ nkeka no mfimfini sɛ wode adeɛ a ɛma adeɛ yɛ kɛse hwɛ a. Nhaban a yare aka no dan akokɔsradeɛ na ɛtew. Yare no firi nhaban a ɛwɔ ase so kɔ soro.",
            causes = "Mmoawa Septoria lycopersici. Ɛwɔ asase mu na ɛtena nwira a yare aka mu. Ɛfa osutɔ mpete, nsuo a wɔgu firi soro, ne nnua a yare aka a wɔsɔ mu so trɛw. Ahuhuro (20 kɔsi 25 °C) ne bosuo a ɛtena nhaban so kyɛ boa no.",
            effects = "Nhaban a ɛtew firi ase kɔ soro tew aduane a dua no yɛ so na ɛma awia ka aba no. Nnɔbaeɛ hwere a ɛyɛ ɔha mu 30 kɔsi 60 bu so wɔ mfuo a wɔnhwɛ so mu wɔ fɔmm mmerɛ mu. Nhaban a ɛtew mpɛn pii ma dua no yɛ mmerɛw na ɛtew mfe no nnɔbaeɛ nyinaa so. Aba a aka no su nso sɛe esiane awia nti.",
            prevention = "Fa abɔdeɛ nneɛma a mu yɛ duru (sentimita 5 kɔsi 8) kata dua no ase na osutɔ mmpete asase (yare nsɛso firibea kɛse) nkɔ nhaban a ɛwɔ ase so. Twitwa nhaban a ɛwɔ ase sɛ dua no nyin a. Fa nsuo a ɛsensen di dwuma — mma nsuo nnka nhaban. Ma kwan a ɛboro sentimita 60 nna hɔ na mframa afa mu. Sesa nnɔbaeɛ mfe 3 na fa nnɔbaeɛ a ɛnyɛ ntoos abusua di akyi.",
            organicMitigation = "• Fa nneɛma kata asase so yie twa nnua no ho hyia (nwura, ɛmo ho ntoma, sare a awo): Esi asase mpete kwan, na ɛno ne yare no firibea kɛse.\n• Twitwa nhaban a ɛwɔ ase a yare aka no ntɛm na yi firi afuo no mu.\n• Petepete kɔbere sulfate (Bordeaux mixture) nnansa 10 kɔsi 14 biara sɛ ɔbanbɔ wɔ fɔmm mmerɛ mu.\n• Petepete bicarbonate ne neem ngo nkabom (neem ngo atere kɛse 1 + baking soda atere ketewa 1 wɔ lita nsuo biara mu): Ɛsesa nhaban ani tebea na esi mmoawa nsɛso fifi kwan.\n• Petepete compost nsuo wɔ nhaban so: Mmoawa pa ne Septoria di akan na wosi ne kwan.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500 anaa Daconil 2787): Eyi na wɔde di dwuma kɛse; fa di dwuma nnansa 7 kɔsi 10 biara sɛ ɔbanbɔ.\n• Mancozeb (Dithane M-45): Aduro a ɛbɔ ho ban yie; fa di dwuma sesa ne Chlorothalonil ntam.\n• Azoxystrobin (Amistar anaa Quadris): Ɛkɔ dua no mu; ɛyɛ adwuma yie; fa di dwuma nnansa 14 biara.\n• Propiconazole (Tilt 250EC): DMI aduro a ɛkɔ dua mu; fa di dwuma wɔ yare no mfiaseɛ na ɛsa no.\n• Trifloxystrobin + Tebuconazole (Nativo 75WG): Nkabom pa; ɛsa Septoria yie wɔ mfe no nyinaa mu."
        )
    )
}
